<script setup lang="ts">
import {ref,onMounted} from 'vue'
import {ElMessage} from 'element-plus'
import {ops,listOps,errorMessage,exportSheet} from '@/api/asset-ops'
import TableSortHeader from '@/components/TableSortHeader.vue'
import TablePager from '@/components/TablePager.vue'
import {useServerTable} from '@/features/table/useServerTable'
import {useColumnWidths} from '@/features/table/useColumnWidths'
const users=ref<any[]>([])
const {rows,total,page,pageSize,loading,failed,search,query,tableRef,sortBy,onSortChange,reload,clearSearch,settled}=useServerTable<any>(params=>ops(`audit?${new URLSearchParams(Object.entries(params).map(([key,value])=>[key,String(value)]))}`),50,e=>ElMessage.error(errorMessage(e)))
const {columnWidths,resizeColumn}=useColumnWidths({createdAt:180,action:140,resourceType:150,requestId:220})
function format(value:string){try{return JSON.stringify(JSON.parse(value),null,2)}catch{return value}}
function name(id:string){return users.value.find(u=>u.id===id)?.name||id||'系统任务'}
onMounted(async()=>{try{users.value=await listOps('operators')}catch{}})
</script>
<template><div class="ops-toolbar between"><span class="ops-muted">资产与备件变更记录 · 不展示账号口令及 LDAP 配置内容</span><el-button :disabled="!settled" @click="exportSheet('资产操作审计',rows.map(r=>({时间:r.createdAt,操作人:name(r.userId),操作:r.action,对象类型:r.resourceType,对象ID:r.resourceId,变更前:r.before,变更后:r.after,请求ID:r.requestId})))">导出当前页</el-button></div><el-input v-model="search" clearable aria-label="搜索资产操作审计" placeholder="搜索操作、对象类型或请求ID" style="max-width:360px;margin-bottom:12px"/><el-alert v-if="failed" title="加载失败，请重试；当前行可能不是最新查询结果" type="error" :closable="false"/><el-button v-if="failed" @click="reload">重试</el-button><el-table :aria-busy="loading||search!==query" ref="tableRef" @sort-change="onSortChange" :data="rows" v-loading="loading"><el-table-column label="时间" prop="createdAt" :width="columnWidths['createdAt']" sortable="custom"><template #header><TableSortHeader label="时间" :width="columnWidths['createdAt']" @sort="sortBy('createdAt')" @resize="resizeColumn('createdAt',$event)"/></template><template #default="{row}">{{new Date(row.createdAt).toLocaleString()}}</template></el-table-column><el-table-column label="操作人" min-width="140"><template #default="{row}">{{name(row.userId)}}</template></el-table-column><el-table-column label="操作" prop="action" :width="columnWidths['action']" sortable="custom"><template #header><TableSortHeader label="操作" :width="columnWidths['action']" @sort="sortBy('action')" @resize="resizeColumn('action',$event)"/></template></el-table-column><el-table-column label="对象类型" prop="resourceType" :width="columnWidths['resourceType']" sortable="custom"><template #header><TableSortHeader label="对象类型" :width="columnWidths['resourceType']" @sort="sortBy('resourceType')" @resize="resizeColumn('resourceType',$event)"/></template></el-table-column><el-table-column prop="requestId" label="请求ID" :width="columnWidths.requestId" sortable="custom"><template #header><TableSortHeader label="请求ID" :width="columnWidths.requestId" @sort="sortBy('requestId')" @resize="resizeColumn('requestId',$event)"/></template></el-table-column><el-table-column label="变更详情" min-width="260"><template #default="{row}"><details><summary>查看变更前后</summary><pre class="ops-audit-json">{{format(row.before)}}</pre><pre class="ops-audit-json">{{format(row.after)}}</pre></details></template></el-table-column><template #empty><el-empty :description="failed?'加载失败':query?'没有匹配记录':'暂无操作记录'"><el-button v-if="query" @click="clearSearch">清除筛选</el-button></el-empty></template></el-table><TablePager v-model:page="page" v-model:page-size="pageSize" :total="total" label="资产操作审计"/></template>
<style scoped>summary{color:#537cbd;cursor:pointer;font-size:12px}.ops-audit-json{padding:12px;background:var(--color-canvas);max-height:260px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:10px}</style>
